let current:Lang=(localStorage.getItem("estateflowLang") as Lang)||"ru";
if(!["ru","hy","en"].includes(current))current="ru";
export const getLang=()=>current;
const syncDocumentLang=()=>{if(typeof document!=="undefined")document.documentElement.lang=current};
syncDocumentLang();
export const setLang=(lang:Lang)=>{current=lang;localStorage.setItem("estateflowLang",lang);syncDocumentLang()};
export const t=(key:string,vars:Vars={})=>{
  const template=dict[current][key]??dict.ru[key]??key;
  return Object.entries(vars).reduce((value,[name,replacement])=>value.replaceAll(`{${name}}`,String(replacement)),template);
};
export const locale=()=>current==="hy"?"hy-AM":current==="en"?"en-US":"ru-RU";

